import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as a,c as r,ak as n}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.CXVl0N2D.webp",s="/projects/esp32Sensor/en/latest/assets/2.Ifa_Y3gw.webp",l="/projects/esp32Sensor/en/latest/assets/3.DEUfyN_k.webp",d="/projects/esp32Sensor/en/latest/assets/4.DmtGFMLl.webp",y=JSON.parse('{"title":"12. Raindrop Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/12. Raindrop Sensor.md","filePath":"docs/12. Raindrop Sensor.md"}'),c={name:"docs/12. Raindrop Sensor.md"};function h(p,e,g,m,u,f){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_12-raindrop-sensor" tabindex="-1">12. Raindrop Sensor <a class="header-anchor" href="#_12-raindrop-sensor" aria-label="Permalink to &quot;12. Raindrop Sensor&quot;">​</a></h1><h2 id="_12-1-introduction" tabindex="-1">12.1 Introduction <a class="header-anchor" href="#_12-1-introduction" aria-label="Permalink to &quot;12.1 Introduction&quot;">​</a></h2><p>Designed to detect rainfall intensity, the raindrop sensor converts measurement results into analog signal outputs for weather monitoring. The sensing board features an immersion gold finish, enhancing corrosion resistance and extending operational lifespan.</p><img loading="lazy" height="1768" width="1527" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_12-2-technical-specifications" tabindex="-1">12.2 Technical Specifications <a class="header-anchor" href="#_12-2-technical-specifications" aria-label="Permalink to &quot;12.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Surface material</td><td style="text-align:center;">Immersion gold</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">71.2 × 48.2 × 10.6 mm</td></tr></tbody></table><h2 id="_12-3-hands-on-project" tabindex="-1">12.3 Hands-On Project <a class="header-anchor" href="#_12-3-hands-on-project" aria-label="Permalink to &quot;12.3 Hands-On Project&quot;">​</a></h2><h3 id="_12-3-1-project-overview" tabindex="-1">12.3.1 Project Overview <a class="header-anchor" href="#_12-3-1-project-overview" aria-label="Permalink to &quot;12.3.1 Project Overview&quot;">​</a></h3><p>This project uses the raindrop sensor to collect analog moisture readings, setting multiple thresholds to trigger different tones on the buzzer. Drip water onto the sensor surface to change the detected reading, producing tiered audio alerts and exploring threshold-based conditional logic for analog inputs.</p><h3 id="_12-3-2-hardware-wiring" tabindex="-1">12.3.2 Hardware Wiring <a class="header-anchor" href="#_12-3-2-hardware-wiring" aria-label="Permalink to &quot;12.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the raindrop sensor to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="825" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_12-3-3-adding-extensions" tabindex="-1">12.3.3 Adding Extensions <a class="header-anchor" href="#_12-3-3-adding-extensions" aria-label="Permalink to &quot;12.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Raindrop sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_12-3-4-complete-program-and-analysis" tabindex="-1">12.3.4 Complete Program and Analysis <a class="header-anchor" href="#_12-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;12.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the reading detected by the raindrop sensor is stored in the variable <code>rainfall</code> to check the following conditions:</p><ul><li><p>If <code>rainfall</code> &gt; 200, the buzzer plays note C7.</p></li><li><p>If <code>rainfall</code> &gt; 140, the buzzer plays note C5.</p></li><li><p>If <code>rainfall</code> &gt; 80, the buzzer plays note C3.</p></li><li><p>If <code>rainfall</code> ≤ 80, the buzzer turns off.</p></li></ul></li><li><p>A 0.1 s delay is added at the end of each loop iteration before repeating the detection cycle.</p></li></ol><img loading="lazy" height="678" width="678" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/12 Raindrop Sensor.sb3</a>.</strong></p></div><h3 id="_12-3-5-program-upload" tabindex="-1">12.3.5 Program Upload <a class="header-anchor" href="#_12-3-5-program-upload" aria-label="Permalink to &quot;12.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_12-3-6-implementation-outcome" tabindex="-1">12.3.6 Implementation Outcome <a class="header-anchor" href="#_12-3-6-implementation-outcome" aria-label="Permalink to &quot;12.3.6 Implementation Outcome&quot;">​</a></h3><p>Once the program upload is complete, drip water onto the surface of the raindrop sensor. When the sensor is dry, the buzzer remains silent. Adding a few drops pushes the reading above 80, sounding note C3. As moisture increases and the value exceeds 140, the tone switches to note C5. Adding more water to push the value above 200 triggers note C7. Wiping the sensor surface dry stops the buzzer immediately.</p>',25)])])}const x=o(c,[["render",h]]);export{y as __pageData,x as default};
